import Foundation

/// Generates the seller's side of a Community (marketplace) chat.
///
/// Two modes, picked automatically — never a hand-off the caller has to think
/// about, same idea as `SupabaseConfig.isConfigured` gating `LocalAuthStore`:
///
/// - **Local (default)**: a keyword-aware reply built from the listing's own
///   title/price/condition/description. No network, works fully offline,
///   zero setup.
/// - **Gemini (opt-in)**: once `GeminiConfig.isConfigured` is true, every
///   reply is generated by the real Gemini API instead, using the same
///   listing context as the prompt. Falls back to the local reply if the
///   network call fails for any reason (offline, bad key, rate limit), so a
///   bad key degrades gracefully instead of breaking the chat.
enum AutoReplyEngine {

    /// Everything the reply needs to know about what's being sold —
    /// resolved by the caller from either the live `MarketplaceListing` (when
    /// it still exists) or the thread's own cached fields.
    struct ListingContext {
        let title: String
        let price: Double
        let isFree: Bool
        let condition: String
        let description: String
        let sellerName: String
    }

    static func reply(to buyerMessage: String, listing: ListingContext) async -> String {
        if GeminiConfig.isConfigured, let aiReply = try? await geminiReply(to: buyerMessage, listing: listing) {
            return aiReply
        }
        return localReply(to: buyerMessage, listing: listing)
    }

    // MARK: - Gemini (real AI, opt-in via GeminiConfig)

    private static func geminiReply(to buyerMessage: String, listing: ListingContext) async throws -> String {
        let priceText = listing.isFree ? "free" : "₱\(Int(listing.price))"
        let prompt = """
        You are \(listing.sellerName), replying as the seller on a Philippines \
        peer-to-peer marketplace app called OneMart. You're selling "\(listing.title)" \
        (\(listing.condition) condition, \(priceText)). Listing description: \
        "\(listing.description)".

        A buyer just messaged you: "\(buyerMessage)"

        Reply in 1-2 short, friendly sentences as the seller would, in a casual \
        Filipino-English ("Taglish") tone. Answer their question directly using the \
        listing details above. Don't repeat the listing details verbatim, don't use \
        markdown, and don't mention you're an AI.
        """

        // Try each configured model in order — if one is retired, rate
        // limited, or unavailable for this key, the next one gets a chance
        // before `reply(...)` falls back to the local reply.
        var lastError: Error = URLError(.badServerResponse)
        for model in GeminiConfig.models {
            do {
                return try await requestReply(prompt: prompt, model: model)
            } catch {
                lastError = error
                #if DEBUG
                print("[AutoReplyEngine] \(model) failed: \(error.localizedDescription)")
                #endif
            }
        }
        throw lastError
    }

    private static func requestReply(prompt: String, model: String) async throws -> String {
        var request = URLRequest(url: GeminiConfig.endpoint(for: model))
        request.httpMethod = "POST"
        request.timeoutInterval = 15
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        // Sending the key both ways (query param + header) maximizes
        // compatibility with the newer "AQ." auth-key format, which some
        // client libraries have only partially supported during its rollout.
        request.setValue(GeminiConfig.apiKey, forHTTPHeaderField: "x-goog-api-key")

        var generationConfig: [String: Any] = ["maxOutputTokens": 120, "temperature": 0.7]
        if model.hasPrefix("gemini-2.5") {
            // 2.5 models can spend the whole output budget "thinking" and
            // return no text — a one-line chat reply doesn't need it.
            generationConfig["thinkingConfig"] = ["thinkingBudget": 0]
        }
        request.httpBody = try JSONSerialization.data(withJSONObject: [
            "contents": [["parts": [["text": prompt]]]],
            "generationConfig": generationConfig
        ])

        let (data, response) = try await URLSession.shared.data(for: request)
        guard let http = response as? HTTPURLResponse, (200...299).contains(http.statusCode) else {
            #if DEBUG
            let code = (response as? HTTPURLResponse)?.statusCode ?? -1
            print("[AutoReplyEngine] HTTP \(code): \(String(data: data, encoding: .utf8) ?? "")")
            #endif
            throw URLError(.badServerResponse)
        }

        let decoded = try JSONDecoder().decode(GeminiResponse.self, from: data)
        let text = (decoded.candidates?.first?.content?.parts ?? [])
            .compactMap(\.text)
            .joined()
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else {
            throw URLError(.cannotParseResponse)
        }
        return text
    }

    private struct GeminiResponse: Decodable {
        struct Candidate: Decodable {
            struct Content: Decodable {
                struct Part: Decodable { let text: String? }
                let parts: [Part]?
            }
            let content: Content?
        }
        let candidates: [Candidate]?
    }

    // MARK: - Local fallback (default, fully offline)

    /// Keyword-matched reply built from the listing's own details, so the
    /// default experience (no API key needed) still answers *this* buyer's
    /// question instead of picking a random unrelated line.
    private static func localReply(to buyerMessage: String, listing: ListingContext) -> String {
        let text = buyerMessage.lowercased()
        let priceText = listing.isFree ? "Free na siya" : "₱\(Int(listing.price))"

        if text.contains("available") || text.contains("pa ba") || text.contains("still") {
            return "Hi! Yes, \"\(listing.title)\" is still available po."
        }
        if text.contains("price") || text.contains("magkano") || text.contains("nego") || text.contains("tawad") || text.contains("less") {
            return listing.isFree
                ? "It's free na po, first come first served!"
                : "\(priceText) po — pwede pa natin pag-usapan kung personal meet-up."
        }
        if text.contains("condition") || text.contains("ok ba") || text.contains("okay ba") || text.contains("defect") {
            let detail = listing.description.isEmpty ? "well taken care of!" : listing.description
            return "It's \(listing.condition.lowercased()) condition po — \(detail)"
        }
        if text.contains("where") || text.contains("location") || text.contains("saan") || text.contains("meet") || text.contains("pickup") || text.contains("pick up") {
            return "I'm based near the listing's pin po. Meet-up or OneMart Delivery, whichever is convenient for you."
        }
        if text.contains("deliver") || text.contains("ship") || text.contains("send") {
            return "Yes, you can arrange a OneMart Delivery for this one — just tap \"Arrange OneMart Delivery\" on the listing."
        }

        return "Hi! Thanks for messaging about \"\(listing.title)\" — \(priceText) po. Let me know what you'd like to ask!"
    }
}
